// MPC node core: shared types. Source of truth: /shared. Copies are generated by `npm run sync-shared`.
// The DKLs23 library is injected (MpcLib) so the same round logic runs with
// @silencelaboratories/dkls-wasm-ll-node on the servers and dkls-wasm-ll-web in the browser.

/** A protocol message as it travels in JSON (CDC annex A). `to: null` means broadcast. */
export type WireMessage = { from: number; to: number | null; payload: string };

export const KEYGEN_PARTICIPANTS = 3;
export const KEYGEN_THRESHOLD = 2;
/** Last round of key generation (CDC 3.5): the key share exists after it. */
export const KEYGEN_LAST_ROUND = 5;
/** Last round of signing that is stored: after round 4 the pre-signature is ready. */
export const SIGN_PRESIGN_ROUND = 4;

// Structural view of the library (types of version 1.2.0). Method syntax on purpose.
export interface MpcMessage {
  from_id: number;
  to_id?: number;
  readonly payload: Uint8Array;
  free(): void;
}
export interface MpcKeyshare {
  readonly partyId: number;
  readonly publicKey: Uint8Array;
  toBytes(): Uint8Array;
  free(): void;
}
export interface MpcKeygenSession {
  toBytes(): Uint8Array;
  createFirstMessage(): MpcMessage;
  calculateChainCodeCommitment(): Uint8Array;
  handleMessages(msgs: any[], commitments?: any[]): MpcMessage[];
  keyshare(): MpcKeyshare;
  free(): void;
}
export interface MpcSignSession {
  toBytes(): Uint8Array;
  createFirstMessage(): MpcMessage;
  handleMessages(msgs: any[]): MpcMessage[];
  lastMessage(messageHash: Uint8Array): MpcMessage;
  combine(msgs: any[]): any[];
  free(): void;
}
export interface MpcLib {
  KeygenSession: { new (participants: number, threshold: number, partyId: number): MpcKeygenSession; fromBytes(bytes: Uint8Array): MpcKeygenSession };
  Keyshare: { fromBytes(bytes: Uint8Array): MpcKeyshare };
  Message: { new (payload: Uint8Array, from: number, to?: number): MpcMessage };
  SignSession: { new (keyshare: any, chainPath: string): MpcSignSession; fromBytes(bytes: Uint8Array): MpcSignSession };
}

/**
 * Stable error codes returned by the node core.
 * ABORT_BAN_PARTY: the library identified a cheating party (`banParty` = its keyshare party id).
 * PROTOCOL_ERROR: any other failure inside the protocol. Never retry on the same session.
 * SESSION_NOT_FOUND: no stored state for this session and round (unknown, expired, replayed or already used).
 * BAD_REQUEST: the caller sent a wrong round, wrong senders or malformed messages.
 * STORAGE_ERROR: a stored record could not be decrypted or parsed (wrong key, tampered bytes).
 */
export type MpcErrorCode = "ABORT_BAN_PARTY" | "PROTOCOL_ERROR" | "SESSION_NOT_FOUND" | "BAD_REQUEST" | "STORAGE_ERROR";

/** `message` is safe to return to a caller. Library text stays in `detail` for server logs (it holds no key material). */
export class MpcError extends Error {
  readonly code: MpcErrorCode;
  readonly banParty?: number;
  readonly detail?: string;
  constructor(code: MpcErrorCode, message: string, extra: { banParty?: number; detail?: string } = {}) {
    super(message);
    this.name = "MpcError";
    this.code = code;
    this.banParty = extra.banParty;
    this.detail = extra.detail;
  }
}

/** Maps anything thrown by the library to a stable code. An MpcError passes through unchanged. */
export function toMpcError(err: unknown): MpcError {
  if (err instanceof MpcError) return err;
  const detail = String((err as { message?: unknown } | null)?.message ?? err).slice(0, 200);
  // The library throws a plain Error with a `banParty` property (zero is a valid party id).
  const ban = (err as { banParty?: unknown } | null)?.banParty;
  if (typeof ban === "number" && Number.isInteger(ban)) return new MpcError("ABORT_BAN_PARTY", "Protocol aborted: a party misbehaved", { banParty: ban, detail });
  return new MpcError("PROTOCOL_ERROR", "Protocol error", { detail });
}

/** free() can itself throw after a failed round or on a consumed object: it must never hide the real error. */
export function safeFree(obj: { free(): void } | null | undefined): void {
  try {
    obj?.free();
  } catch {
    // The object is unusable either way.
  }
}

// Base64 without Buffer, so this file also runs in the browser.
export function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(s);
}
export function fromBase64(text: string): Uint8Array {
  if (typeof text !== "string" || !/^[A-Za-z0-9+/]*={0,2}$/.test(text)) throw new MpcError("BAD_REQUEST", "Invalid base64 payload");
  const s = atob(text);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}
export function toHex(bytes: Uint8Array): `0x${string}` {
  return `0x${Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("")}`;
}
